/* 자동 생성 — scripts/proposal-sync.mjs · 원본 data/proposal/i18n/en.json */
export default {"industries":{"manufacturing":{"label":"Manufacturing and production plants","short":"Manufacturing","hero":"Let your equipment speak up before the line stops"},"bio_pharma":{"label":"Pharma, biotech and research labs","short":"Biotech","hero":"24/7 environmental records that protect samples and batches"},"datacenter":{"label":"Data centers and server rooms","short":"IDC","hero":"Outages start with the environment"},"building_fm":{"label":"Commercial buildings and mixed-use FM","short":"Buildings","hero":"Facility management that knows before the complaints come in"},"energy":{"label":"Energy, power and water treatment","short":"Energy","hero":"Distributed plant assets on a single screen"},"cold_chain":{"label":"Retail, cold chain and logistics","short":"Cold chain","hero":"A freezer that fails overnight is too late to catch in the morning"},"public":{"label":"Public sector, defense and infrastructure","short":"Public sector","hero":"Continuous monitoring instead of patrols"},"edu_med":{"label":"Hospitals, schools and care facilities","short":"Hospitals and schools","hero":"An invisible safety net for spaces that care for people"},"food_agri":{"label":"Food service, agriculture and fisheries","short":"Food and agriculture","hero":"A single temperature excursion can decide a whole year's harvest"},"construction":{"label":"Construction and job sites","short":"Construction","hero":"Work changes daily, but safety records never break"},"general":{"label":"Other facilities","short":"Facilities","hero":"Your facility alerts you first, even when no one is there"},"residential":{"label":"Residential, hotels and lodging","short":"Residential and lodging","hero":"Get alerted to room overflows and vacant-unit pipe freezing first"}},"problems":{"downtime":{"label":"Unexpected failures and unplanned downtime of rotating equipment","desc":"Motors, pumps and fans are noticed only after they stop, driving up production and operating losses"},"rounds":{"label":"Burden of manual rounds and logs","desc":"Manual inspection rounds leave gaps at night and on holidays, and records get missed"},"wiring":{"label":"Wiring cost and lead time for wired sensors","desc":"Wiring is difficult in piping, explosion-proof and live operating areas, and costs rise sharply"},"leak":{"label":"Late detection of pipe and equipment leaks","desc":"Leaks are noticed only after they spread to lower floors or equipment, increasing secondary damage"},"flood":{"label":"Heavy rain and flooding response","desc":"Flooding in basement mechanical rooms, parking garages and pits is hard to detect early"},"freeze":{"label":"Winter pipe freezing","desc":"Pipes in vacant units or exposed to outdoor air are found only after they freeze and burst"},"elec_fire":{"label":"Electrical fire and overload risk","desc":"Overheating and overloads in distribution panels and switchboards are hard to spot in advance"},"power_out":{"label":"Delayed awareness of power outages and tripped breakers","desc":"Breaker trips or outages are noticed late, so refrigeration, servers and equipment go down"},"env_quality":{"label":"Process and storage environment (temperature/humidity) excursions","desc":"Temperature and humidity swings lead to quality defects, material corrosion and condensation"},"cleanroom":{"label":"Cleanroom and lab differential pressure control","desc":"Differential pressure and temperature/humidity excursions are hard to confirm in real time"},"cold_storage":{"label":"Refrigeration and freezer temperature excursions","desc":"Freezer failures at night or on weekends force you to discard inventory and samples"},"ultracold":{"label":"Ultra-low temperature storage (deep freezer) excursions","desc":"Temperature excursions of samples and vaccines stored at -80℃ are hard to catch immediately"},"record":{"label":"Temperature records for compliance and audits (HACCP, GMP)","desc":"Manual logs risk omissions and tampering, and audit preparation takes time"},"door_open":{"label":"Doors left open and no access history","desc":"Open doors on refrigerators, warehouses and server rooms are noticed late, causing losses and security gaps"},"hotspot":{"label":"Server rack hot spots and uneven cooling","desc":"Temperature variation across racks shortens equipment life and causes failures"},"energy":{"label":"Excessive HVAC and equipment energy use","desc":"Without knowing where power is being wasted, it is hard to plan savings"},"multi_site":{"label":"Remote, unified management of multiple sites and stores","desc":"Each site is monitored separately, so there is no single view of the overall situation"},"integration":{"label":"Data siloed from existing BAS and SCADA","desc":"Scattered systems prevent unified monitoring and analysis"},"gas":{"label":"Gas and fluid leak risk","desc":"Leaks across large sites are checked by people on foot, leaving accident risk"},"unmanned":{"label":"Monitoring gaps during unmanned and night hours","desc":"Problems that occur when no one is around are found only the next day"},"iaq":{"label":"Indoor air quality and occupant comfort complaints","desc":"Air quality and temperature complaints are frequent, but there is no data to back them up"},"tank_level":{"label":"Manual checks of tank and sump pit levels","desc":"Someone has to go and check levels in person, so overflows and run-dry events are missed"},"structure":{"label":"Safety monitoring for structures and construction sites","desc":"Tilt, vibration and environmental changes are hard to monitor continuously"},"water_temp":{"label":"Sudden changes in water temperature and aquaculture conditions","desc":"Water temperature swings and power outages lead directly to stock die-offs"},"curing":{"label":"Concrete curing and cold-weather heat retention","desc":"Curing temperatures must be measured by staff on foot, and no records are kept"},"toxic_gas":{"label":"Toxic gas (CO, H2S) exposure risk","desc":"Gas concentrations in enclosed spaces and underground facilities are not continuously known"},"emergency":{"label":"Emergency calls and lone-worker incidents","desc":"There is no way to call for help if someone collapses or gets trapped while alone"},"occupancy":{"label":"Space utilization and energy wasted on empty spaces","desc":"HVAC and lighting stay on when no one is there"},"meter":{"label":"Manual reading of electricity, water and gas meters","desc":"Meter readings are written by hand, so abnormal usage is found only at month-end"},"legacy_alarm":{"label":"Existing equipment alarms sound only on site","desc":"Alarms on annunciator and control panels are noticed only if someone is standing nearby"}},"goals":{"downtime":"Reduce unplanned downtime","labor":"Reduce inspection staff and time","loss":"Reduce accident damage and spoilage losses","response":"Respond faster when problems occur","energy":"Cut energy and operating costs","compliance":"Automate compliance and audit records","integration":"Unify monitoring of scattered systems","capex":"Lower installation costs (go wireless)","safety":"Prevent safety incidents and fires"},"sensors":{"vib":"Wireless vibration and acceleration sensor","temp":"Wireless temperature sensor","hum":"Wireless temperature and humidity sensor","cold":"Ultra-low temperature sensor (probe type)","tc":"Thermocouple (high-temperature) sensor","rope":"Water detection rope sensor","leak":"Wireless water leak sensor (spot/puck type)","current":"AC and 3-phase current sensor","volt":"Voltage detection sensor (power outage detection)","dp":"Differential pressure sensor","aq":"Air quality (PM) sensor","door":"Open/closed (door) sensor","motion":"Motion and occupancy sensor","press":"Pressure sensor","level":"Ultrasonic distance (water level) sensor","analog":"4-20mA analog input","soil":"Soil moisture sensor","co2":"Carbon dioxide (CO2) sensor","co":"Carbon monoxide (CO) sensor","h2s":"Hydrogen sulfide (H2S) sensor","dry":"Dry contact input","pulse":"Pulse counter","airflow":"Air velocity (airflow) sensor","light":"Light (lux) sensor","button":"Call button"},"scales":{"1개소 · 감시 포인트 20개 이하":"1 site · up to 20 monitoring points","1개소 · 20~100개":"1 site · 20-100 points","2~5개소 · 100~300개":"2-5 sites · 100-300 points","6개소 이상 · 300개 이상":"6+ sites · 300+ points","아직 모름":"Not sure yet"},"timelines":{"1개월 이내":"Within 1 month","3개월 이내":"Within 3 months","올해 안":"Within this year","정보 수집 단계":"Just researching"},"playbook":{"의약품 생산·연구 현장에서 원료·시료·제품은 정해진 온도·환경 조건에서만 가치를 유지합니다. 환경 이탈은 제품 손실에 더해 일탈 조사·CAPA·감사 대응 부담으로 이어지므로, 이탈을 즉시 알고 기록을 빠짐없이 남기는 체계가 중요합니다.":"In pharmaceutical production and research, raw materials, samples and products retain their value only under defined temperature and environmental conditions. Excursions lead not only to product loss but also to deviation investigations, CAPA and audit burden, so a system that flags excursions immediately and keeps complete records is essential.","야간·주말 보관 설비 이탈":"Storage equipment excursions at night and on weekends","딥프리저·냉장고·인큐베이터의 컴프레서 고장이나 문 닫힘 불량이 야간·주말에 생기면 다음 근무일에야 발견됩니다. 해당 시료·원료는 재평가나 폐기 대상이 됩니다.":"When a compressor fails or a door does not close properly on a deep freezer, refrigerator or incubator at night or on the weekend, it is found only on the next working day. The affected samples and materials then face re-evaluation or disposal.","환경 기록과 감사 대응":"Environmental records and audit readiness","온도·차압을 차트 기록계나 수기로 관리하면 누락과 판독 오류가 생기고, 감사 때 기간별 기록을 찾아 정리하는 데 시간이 걸립니다.":"Managing temperature and differential pressure with chart recorders or manual logs leads to omissions and reading errors, and pulling records together by period for audits takes time.","클린룸 차압·온습도 이탈":"Cleanroom differential pressure and temperature/humidity excursions","출입·도어 개방, 공조기·필터 상태 변화로 등급 구역 간 차압이 흔들립니다. 짧은 이탈은 현장 표시기로만 보이고 기록에 남지 않기도 합니다.":"Door openings and changes in air handler or filter condition cause pressure differentials between graded zones to fluctuate. Brief excursions may appear only on local indicators and never reach the record.","유틸리티 설비 경보 공백":"Utility equipment alarm gaps","칠러·항온항습기·WFI·클린스팀 계통 경보가 기계실 제어반에만 표시되어, 시설팀이 자리를 비우면 대응이 늦어집니다. 정전 시 영향 설비 파악도 늦습니다.":"Alarms from chillers, precision air conditioners (CRAC), WFI and clean steam systems show only on mechanical room control panels, so response is delayed when the facilities team is away. Identifying affected equipment during a power outage is also slow.","원료·자재 창고":"Raw material and supply warehouse","세포은행·시료 보관실":"Cell bank and sample storage","세포배양(USP)":"Cell culture (USP)","정제(DSP)":"Purification (DSP)","완제 충전·무균 구역":"Fill-finish and aseptic area","완제품 보관·출하":"Finished goods storage and shipping","유틸리티(칠러·WFI·공조)":"Utilities (chillers, WFI, HVAC)","시설·유틸리티팀(Engineering)":"Facilities and utilities team (Engineering)","품질보증(QA)·밸리데이션팀":"Quality assurance (QA) and validation team","생산·제조팀":"Production and manufacturing team","연구·실험실 운영팀":"Research and lab operations team","가시화":"Visibility","알림·대응 체계":"Alerts and response","시스템 연동":"System integration","자동 제어":"Automated control","예측·최적화":"Prediction and optimization","바이오의약품 생산·CDMO":"Biopharmaceutical manufacturing and CDMO","고객사 감사 대응 부담":"Burden of client audits","CDMO는 고객사별 감사에서 보관·공정 구역 환경 기록을 반복 제시해야 합니다. 기록이 시스템별로 흩어져 있으면 정리에 시간이 걸립니다.":"CDMOs must repeatedly present environmental records for storage and process areas in each client audit. When records are scattered across systems, compiling them takes time.","바이오리액터실":"Bioreactor room","세포은행 보관실":"Cell bank storage room","배지·완충액 준비실":"Media and buffer prep room","합성의약품·제약 생산":"Small-molecule drug and pharmaceutical manufacturing","고형제 공정 습도 편차":"Humidity variation in solid dosage processes","과립·타정·코팅실은 계절과 공조 상태에 따라 습도가 흔들리고 흡습성 원료는 편차에 민감합니다. 실별 편차를 수기로만 남기는 곳이 많습니다.":"Humidity in granulation, tableting and coating rooms fluctuates with the season and HVAC condition, and hygroscopic materials are sensitive to these variations. Many sites record room-by-room variation only by hand.","원료 칭량·보관실":"Raw material weighing and storage room","과립·타정·코팅실":"Granulation, tableting and coating rooms","포장·완제품 창고":"Packaging and finished goods warehouse","연구소·R&D":"Research labs and R&D","흩어진 딥프리저 관리":"Scattered deep freezer management","연구실마다 딥프리저·냉장고를 따로 관리해 전체 현황을 한눈에 보기 어렵고, 설비 자체 경보는 실험실 안에서만 울립니다.":"Each lab manages its own deep freezers and refrigerators, making it hard to see overall status at a glance, and equipment alarms sound only inside the lab.","딥프리저·시료 보관실":"Deep freezer and sample storage room","세포배양·실험실":"Cell culture and labs","LN2·가스 보관 구역":"LN2 and gas storage area","의약품 유통·보관":"Pharmaceutical distribution and storage","냉장 창고·도크 온도 이탈":"Cold storage and dock temperature excursions","입출고가 몰리는 시간대에 도크 도어 개방이 길어지고, 야간 냉장설비 고장은 다음 날 작업 준비 중에 발견되곤 합니다.":"Dock doors stay open longer during peak receiving and shipping hours, and overnight refrigeration failures are often found while preparing for the next day's work.","냉장 창고(2~8℃)":"Cold storage (2-8℃)","상온 보관 창고":"Ambient storage warehouse","입출고 도크":"Receiving and shipping docks","빌딩은 기계실·전기실·주차장·옥상 설비가 층과 동에 흩어져 있고, 소수의 시설팀이 교대로 관리합니다. 누수·동파·전기 이상은 입주사 피해와 민원으로 바로 이어지므로, 사람이 돌기 전에 이상을 먼저 아는 체계가 필요합니다.":"In buildings, mechanical rooms, electrical rooms, parking garages and rooftop equipment are spread across floors and wings, and a small facilities team manages them in shifts. Leaks, pipe freezing and electrical faults turn directly into tenant damage and complaints, so you need a system that flags problems before anyone makes the rounds.","누수·배관 파손 늦은 발견":"Late detection of leaks and pipe bursts","PD·샤프트·천장 속 배관과 FCU 드레인 누수는 눈에 띄지 않다가 아래층 천장 얼룩이나 입주사 신고로 처음 드러납니다.":"Leaks from piping in pipe ducts, shafts and ceilings and from FCU drains go unnoticed until they first appear as ceiling stains on the floor below or tenant reports.","겨울철 동파·여름철 침수":"Winter pipe freezing and summer flooding","외기에 노출된 옥상·주차장 배관은 한파 때 얼기 쉽고, 집중호우 때 지하 집수정이 넘치면 기계실 설비가 물에 잠깁니다.":"Rooftop and parking garage piping exposed to outdoor air freezes easily in cold snaps, and when basement sump pits overflow in heavy rain, mechanical room equipment ends up underwater.","전기실·분전반 이상 징후":"Warning signs in electrical rooms and distribution panels","층별 분전반과 수배전반의 과부하·단자 과열은 정기 점검 사이에 진행되고, 차단기 트립이 난 뒤에야 원인을 찾게 됩니다.":"Overloads and terminal overheating in floor distribution panels and main switchgear develop between scheduled inspections, and causes are investigated only after a breaker trips.","순회점검·검침 수기 부담":"Burden of manual rounds and meter reading","기계실 운전일지, 층별 온도, 계량기 검침을 사람이 적어 야간·휴일 공백이 생기고, 관리비 정산 근거 정리에 시간이 듭니다.":"Mechanical room operating logs, floor temperatures and meter readings are written by hand, leaving gaps at night and on holidays, and compiling the basis for maintenance fee billing takes time.","수변전실·전기실":"Substation and electrical rooms","기계실(열원·펌프)":"Mechanical room (heat source, pumps)","공조실·옥상 설비":"Air handling room and rooftop equipment","PD·샤프트·화장실":"Pipe ducts, shafts and restrooms","사무 공간·공용부":"Office spaces and common areas","지하주차장·집수정":"Underground parking and sump pits","방재실·중앙감시실":"Disaster prevention room and central monitoring room","시설관리팀(기계·전기 기사)":"Facility management team (mechanical and electrical engineers)","PM·자산관리(임대 운영)":"PM and asset management (leasing operations)","안전·소방관리자":"Safety and fire safety manager","BAS·IT 운영 담당":"BAS and IT operations","오피스·임대빌딩":"Office and leased buildings","입주사 전산실·탕비실 누수":"Leaks from tenant server rooms and pantries","입주사가 설치한 항온항습기, 탕비실 정수기·싱크 배관은 관리 사각지대라 누수가 아래층까지 번진 뒤에 알게 됩니다.":"Tenant-installed precision air conditioners (CRAC) and pantry water purifier and sink piping are management blind spots, so leaks are noticed only after spreading to the floor below.","입주사 전산실":"Tenant server rooms","로비·엘리베이터 홀":"Lobby and elevator hall","복합쇼핑몰·상업시설":"Shopping malls and commercial facilities","폐점 후 설비 이상":"Equipment faults after closing","영업 종료 후 인력이 줄어든 시간에 누수, 매장 냉장설비 정지, 배수 역류가 생기면 다음 날 개점 준비 때 발견됩니다.":"When leaks, store refrigeration shutdowns or drain backflows occur after hours with reduced staff, they are found the next day while preparing to open.","푸드코트 주방 배기·가스":"Food court kitchen exhaust and gas","푸드코트 주방은 배기팬 이상, 덕트 주변 과열, 연소기구 주변 CO 상승이 겹치기 쉬운 구역입니다.":"Food court kitchens are prone to overlapping risks: exhaust fan faults, overheating around ducts and rising CO near combustion appliances.","푸드코트·임대 주방":"Food court and tenant kitchens","하역장·쓰레기 집하장":"Loading dock and waste collection area","공조기·에스컬레이터":"Air handlers and escalators","복합건물·주상복합":"Mixed-use and residential-commercial complexes","용도별 관리 주체 분산":"Management split by use","주거·상가·오피스 관리 주체가 달라 공용 기계실·주차장 이상을 누가 먼저 알고 대응할지 불분명한 경우가 많습니다.":"With separate management for residential, retail and office areas, it is often unclear who should detect and respond first to problems in shared mechanical rooms and parking garages.","공용 기계실·물탱크실":"Shared mechanical room and water tank room","상가 저층부 배관 구간":"Piping in lower-level retail floors","지하주차장 램프":"Underground parking ramps","콜드체인은 입고·보관·피킹·출고·운송·매장 진열 중 어느 한 구간에서 온도가 끊겨도 상품 가치가 떨어집니다. 냉동기 정지, 도크 문 열림, 정전을 늦게 알면 폐기와 클레임으로 이어지므로 구간별 상시 기록이 필요합니다.":"In the cold chain, product value drops if temperature control breaks at any stage: receiving, storage, picking, shipping, transport or store display. Late awareness of freezer shutdowns, open dock doors or power outages leads to spoilage and claims, so continuous records for each stage are essential.","야간·주말 냉동기 정지":"Freezer shutdowns at night and on weekends","컴프레서 트립이나 성에 과다로 냉동기가 멈춰도 창고 온도가 서서히 올라, 근무 시간이 되어서야 알게 되는 경우가 많습니다.":"Even when a freezer stops due to a compressor trip or excessive frost, warehouse temperature rises gradually, so it is often noticed only when staff arrive.","도크·냉장실 문 열림 방치":"Dock and cold room doors left open","입출고가 몰리는 시간에 도크 도어와 냉장실 문이 열린 채 방치되면 실내 온도가 오르고 증발기 결빙이 빨라집니다.":"When dock doors and cold room doors are left open during peak receiving and shipping hours, room temperature rises and evaporator icing accelerates.","온도 기록 수기 작성":"Manual temperature logs","하루 몇 차례 온도계를 보고 적는 방식은 기록 사이의 이탈을 보여주지 못하고, 화주·감사 요청 때 자료 정리에 시간이 듭니다.":"Reading and writing down thermometer values a few times a day cannot show excursions between readings, and compiling data for shipper or audit requests takes time.","다수 거점 통합 관리 어려움":"Difficulty managing multiple sites centrally","센터·차량·매장이 지역별로 흩어져 있고 냉동 장비 제조사가 달라, 본사에서 전체 온도 상태를 한눈에 보기 어렵습니다.":"With centers, vehicles and stores spread across regions and refrigeration equipment from different manufacturers, headquarters struggles to see overall temperature status at a glance.","입고 도크·전실":"Receiving dock and anteroom","냉장 보관실":"Refrigerated storage room","냉동 보관실":"Frozen storage room","냉동기실·콘덴서":"Refrigeration machine room and condensers","피킹·분류장":"Picking and sorting area","수배전·비상발전":"Switchgear and emergency generators","출고 도크·상차 대기":"Shipping dock and loading staging","센터 운영·설비팀":"Center operations and facilities team","품질·QA(화주 대응)":"Quality and QA (shipper relations)","물류 운영·현장 관리자":"Logistics operations and site managers","본사 SCM·IT":"Headquarters SCM and IT","저온 물류센터":"Cold storage logistics center","대형 냉동실 온도 편차":"Temperature variation in large freezers","천장고가 높은 냉동실은 랙 상단과 하단, 증발기 근처와 도크 쪽의 온도 차가 커서 한두 곳 측정으로는 실제 상태를 알기 어렵습니다.":"In high-ceiling freezers, temperatures differ widely between the top and bottom of racks and between the evaporator and dock sides, so one or two measurement points cannot show actual conditions.","고단 랙 냉동실":"High-bay rack freezer","화주 전용 보관 구역":"Dedicated shipper storage area","냉동창고 바닥 하부":"Underfloor of freezer warehouse","이커머스 풀필먼트":"E-commerce fulfillment","합포장 구역 온도 노출":"Temperature exposure in consolidated packing areas","냉장·냉동 상품이 상온 합포장 구역과 컨베이어에 오래 머물면 포장 전에 이미 온도가 오를 수 있습니다.":"When refrigerated and frozen goods linger in ambient consolidated packing areas and on conveyors, their temperature may already rise before packing.","출고 마감 전 설비 정지":"Equipment stoppages before shipping cutoff","분류 컨베이어·소터 모터가 피크 시간에 멈추면 냉장 상품이 대기 구역에 쌓이고 출고 마감을 놓칩니다.":"When sorting conveyor and sorter motors stop at peak times, refrigerated goods pile up in staging areas and shipping cutoffs are missed.","냉장 피킹존":"Refrigerated picking zone","합포장·냉매 보관":"Consolidated packing and refrigerant storage","분류 컨베이어·소터":"Sorting conveyors and sorters","냉장·냉동 운송":"Refrigerated and frozen transport","차고지 대기 중 냉동기 정지":"Refrigeration unit shutdowns while parked at the depot","상품을 실은 채 차고지에서 대기하는 차량의 냉동기가 멈추거나 외부 전원이 빠지면 출발 직전에야 발견됩니다.":"When the refrigeration unit stops or shore power disconnects on a loaded vehicle waiting at the depot, it is found only just before departure.","냉동탑차 적재함":"Refrigerated truck cargo box","차고지 외부 전원":"Depot shore power","유통 매장 체인":"Retail store chains","폐점 후 쇼케이스 정지":"Display case shutdowns after closing","영업 종료 후나 휴무일에 쇼케이스·워크인 냉장고가 멈추면 다음 개점 때 발견되어 진열 상품을 폐기하게 됩니다.":"When display cases or walk-in coolers stop after hours or on closed days, the problem is found at the next opening and displayed products must be discarded.","점포별 설비 편차":"Equipment differences across stores","점포마다 냉장설비 제조사와 연식이 달라 고장 양상이 다르고, 본사에서는 어느 점포가 위험한지 알기 어렵습니다.":"Each store has refrigeration equipment of different makes and ages with different failure patterns, so headquarters struggles to tell which stores are at risk.","진열 쇼케이스":"Display cases","워크인 냉장·냉동고":"Walk-in coolers and freezers","점포 분전반·실외기":"Store distribution panels and outdoor condensing units","건설 현장은 공정에 따라 작업 장소와 가설 설비가 계속 바뀌어 유선 계측을 깔기 어렵습니다. 임시 전력, 동절기 양생, 집수정 배수, 밀폐 공간 가스처럼 사람이 돌며 확인하던 항목을 무선으로 상시 기록하면 관리 부담을 줄일 수 있습니다.":"On construction sites, work locations and temporary equipment keep changing as work progresses, making wired instrumentation difficult to install. Recording items that staff used to check on foot, such as temporary power, cold-weather curing, sump pit drainage and gas in enclosed spaces, continuously and wirelessly reduces the management burden.","동절기 콘크리트 양생 관리":"Cold-weather concrete curing management","보온 양생 중 온도를 사람이 야간에도 재러 다니고, 측정값은 수기로 남아 품질 기록이 흩어집니다.":"During insulated curing, staff must measure temperatures even at night, and readings are recorded by hand, leaving quality records scattered.","가설 분전반 과부하":"Temporary distribution panel overloads","공정마다 장비가 늘고 옮겨지면서 가설 분전반 부하가 수시로 바뀝니다. 차단기 트립은 작업이 멈춘 뒤에야 알게 됩니다.":"As equipment is added and moved with each phase of work, loads on temporary distribution panels change constantly. Breaker trips are noticed only after work stops.","터파기·지하층 침수":"Flooding of excavations and basement levels","집중호우 때 집수정 수위와 배수펌프 가동 상태를 사람이 직접 확인해야 하고, 야간에는 확인 공백이 생깁니다.":"During heavy rain, sump pit levels and drainage pump operation must be checked in person, leaving gaps at night.","밀폐 공간 가스·야간 보안":"Gas in enclosed spaces and night-time security","지하층·밀폐 구간에서 발전기나 보온 난로를 쓰면 CO가 쌓일 수 있고, 자재 창고는 야간 출입 확인이 어렵습니다.":"Using generators or heaters in basement levels and enclosed areas can cause CO to build up, and night-time access to material storage is hard to verify.","가설 전기·분전반":"Temporary power and distribution panels","터파기·집수정":"Excavations and sump pits","콘크리트 타설·양생":"Concrete pouring and curing","지하층·밀폐 작업 공간":"Basement levels and enclosed work spaces","가시설·인접 구조물":"Temporary works and adjacent structures","현장 사무실·자재 창고":"Site office and material storage","공무·공사 담당":"Project engineering and construction management","안전관리자(EHS)":"Safety manager (EHS)","현장 전기·설비 담당":"Site electrical and MEP staff","현장 관리·자재 담당":"Site management and materials staff","건축 현장":"Building construction sites","층별 양생 온도 측정 부담":"Burden of measuring curing temperatures floor by floor","층마다 타설 시점이 달라 보온 양생 온도를 잴 위치가 계속 바뀌고, 야간 측정 인력이 필요합니다.":"Each floor is poured at a different time, so the points for measuring insulated curing temperatures keep changing, and night-time measurement staff are needed.","타설 층·보온 천막 내부":"Poured floors and inside insulation tents","지하층 터파기·집수정":"Basement excavations and sump pits","토목·터널·교량":"Civil works, tunnels and bridges","터널 내 배수·환기 확인":"Checking drainage and ventilation in tunnels","굴진이 진행될수록 갱구와 막장 사이가 멀어져 배수펌프·환기팬 상태를 직접 보러 가는 부담이 커집니다.":"As excavation advances, the distance between the portal and the tunnel face grows, making it harder to check drainage pumps and ventilation fans in person.","가시설 진동 추세 관찰":"Tracking vibration trends at temporary works","가시설 주변 장비 진동을 상시로 보기 어렵습니다. 무선 진동 추세는 전문 계측을 보조하는 참고 자료로 활용합니다.":"Equipment vibration around temporary works is hard to monitor continuously. Wireless vibration trends serve as supplementary reference data alongside professional instrumentation.","터널 막장·갱내":"Tunnel face and underground","교량 가시설·인접부":"Bridge temporary works and adjacent areas","외곽 가설 전력·발전기":"Perimeter temporary power and generators","플랜트 시공":"Plant construction","기자재 보관 환경 관리":"Equipment storage environment management","장기 보관 중인 전기·계장 기자재는 습기와 결로로 부식될 수 있지만, 보관 창고 온습도는 수기로 확인합니다.":"Electrical and instrumentation equipment in long-term storage can corrode from moisture and condensation, yet storage warehouse temperature and humidity are checked by hand.","기자재 보관 창고":"Equipment storage warehouse","시운전 전 회전기기":"Rotating equipment before commissioning","가설 사무실·숙소":"Temporary offices and worker housing","데이터센터·전산실은 전력·냉방·항온항습 설비가 멈추면 곧바로 IT 서비스 장애로 이어집니다. BMS·DCIM이 있어도 랙 단위 온도, 이중마루 하부 누수, 구형 설비 경보처럼 보이지 않는 구간이 남아 이를 촘촘히 채우는 모니터링이 필요합니다.":"In data centers and server rooms, any stoppage of power, cooling or precision air conditioning equipment leads straight to IT service outages. Even with BMS and DCIM in place, blind spots remain, such as rack-level temperatures, leaks under raised floors and alarms from legacy equipment, and they need to be closely monitored.","랙 핫스팟·냉방 불균형":"Rack hot spots and uneven cooling","고밀도 랙 증설, 블랭킹 패널 누락, 타공판 배치 변화로 랙 흡기 온도가 구역마다 달라집니다. 실 온도만 보면 국부 과열을 놓칩니다.":"Adding high-density racks, missing blanking panels and rearranged perforated tiles make rack inlet temperatures vary by zone. Watching only room temperature misses localized overheating.","이중마루 하부 누수":"Leaks under raised floors","항온항습기 가습·배수 배관과 냉수 배관이 이중마루 아래를 지나 누수가 생겨도 눈에 띄지 않습니다. 케이블 트레이까지 번진 뒤 발견되기도 합니다.":"CRAC humidifier and drain lines and chilled water piping run under the raised floor, so leaks there go unnoticed. Sometimes they are found only after reaching cable trays.","전원 계통 이상 인지 지연":"Delayed awareness of power path faults","UPS·PDU·분전반 차단기 트립이나 한쪽 전원 계통 상실은 이중화 덕분에 서비스가 유지되어 오히려 늦게 알아채는 경우가 있습니다.":"When a UPS, PDU or panel breaker trips or one power path is lost, redundancy keeps services running, which can actually delay detection.","무인 시간대·구형 경보":"Unmanned hours and legacy alarms","야간·휴일 상주 인력이 적고, 구형 항온항습기·발전기 경보는 기계실 제어반에만 표시되어 관제 화면에 올라오지 않는 경우가 있습니다.":"Few staff are on site at night and on holidays, and alarms from legacy CRAC units and generators may show only on mechanical room control panels without reaching the monitoring screen.","수변전·발전기실":"Substation and generator room","UPS·배터리실":"UPS and battery room","PDU·분전반":"PDUs and distribution panels","전산실(화이트스페이스)":"Server room (white space)","이중마루·항온항습기 주변":"Raised floor and around CRAC units","냉방 기계실":"Cooling plant room","출입 통제 구역·케이지":"Access-controlled areas and cages","시설·전기팀(데이터센터 운영)":"Facilities and electrical team (data center operations)","IT 인프라·NOC팀":"IT infrastructure and NOC team","보안·출입 관리":"Security and access control","에너지·ESG 담당":"Energy and ESG","코로케이션·클라우드 IDC":"Colocation and cloud IDC","고객 랙 환경 근거 요구":"Customer demands for rack environment evidence","입주 고객이 장비 장애 시 랙 온습도·전원 이력을 요청하지만, 실 단위 센서만으로는 랙별 근거를 제시하기 어렵습니다.":"Tenants request rack temperature, humidity and power history after equipment failures, but room-level sensors alone cannot provide per-rack evidence.","고객 전용 케이지":"Customer cages","고밀도 랙 구역":"High-density rack area","기업 전산실":"Corporate server rooms","소규모 전산실 감시 공백":"Monitoring gaps in small server rooms","서버실 항온항습기 고장이나 주변 배관 누수를 퇴근 후 알 방법이 없어, 다음 날 출근해서야 장애를 확인하는 경우가 있습니다.":"There is no way to learn about a server room CRAC failure or a nearby pipe leak after hours, so outages are sometimes found only when staff arrive the next day.","서버실":"Server room","항온항습기·배관 주변":"Around CRAC units and piping","통신 국사·기지국":"Telecom central offices and cell sites","분산 무인 시설 원격 감시":"Remote monitoring of distributed unmanned sites","지역별 국사와 기지국 함체를 순회 점검으로 관리하면 냉방기 고장이나 정전을 출동 전까지 정확히 알기 어렵습니다.":"When regional central offices and cell site enclosures are managed through patrols, cooling failures or power outages cannot be pinpointed before a crew is dispatched.","통신 국사 장비실":"Telecom equipment room","옥외 기지국 함체":"Outdoor cell site enclosures","지하 통신구·맨홀":"Underground utility tunnels and manholes","병원·학교·요양시설은 환자·학생·어르신이 머무는 공간이라 설비 이상이 곧 안전 문제로 이어집니다. 약품·백신 냉장 보관, 야간·방학 무인 시간, 누수·정전 대응을 적은 시설 인력으로 챙겨야 합니다.":"Hospitals, schools and care homes house patients, students and seniors, so equipment faults quickly become safety issues. Small facility teams must handle cold storage of medicines and vaccines, unmanned hours at night and during breaks, and leak and outage response.","약품·백신 냉장고 이탈":"Medicine and vaccine refrigerator excursions","병동·약제부·보건실 냉장고가 여러 곳에 흩어져 있고 온도를 수기로 기록합니다. 야간·주말 냉장고 고장은 다음 근무 때에야 발견됩니다.":"Refrigerators in wards, pharmacies and health rooms are scattered across many locations, and temperatures are logged by hand. Refrigerator failures at night or on weekends are found only on the next shift.","운영 중 공간의 배관 누수":"Pipe leaks in occupied spaces","병실·교실 천장 속 배관은 운영 중이라 점검이 어렵습니다. 누수는 천장 얼룩이나 물방울로 드러난 뒤에야 알게 됩니다.":"Piping above ceilings in patient rooms and classrooms is hard to inspect while spaces are in use. Leaks are noticed only after ceiling stains or drips appear.","방학·휴일 설비 공백":"Equipment gaps during breaks and holidays","방학이나 연휴에는 관리 인원이 줄어 보일러실·기계실 이상과 배관 동파, 정전을 늦게 발견합니다.":"During school breaks and long holidays, fewer staff are on hand, so boiler room and mechanical room faults, pipe freezing and power outages are found late.","재실 환경·응급 호출":"Occupant environment and emergency calls","교실·병실·생활실의 환기 부족 민원이 잦고, 화장실·야간 생활실처럼 혼자 있는 공간은 도움을 요청하기 어렵습니다.":"Complaints about poor ventilation in classrooms, patient rooms and living quarters are frequent, and it is hard to call for help from spaces where people are alone, such as restrooms and night-time living quarters.","기계실·보일러실":"Mechanical room and boiler room","전기실·분전반":"Electrical room and distribution panels","약품·백신 냉장고":"Medicine and vaccine refrigerators","병실·교실·생활실":"Patient rooms, classrooms and living quarters","전산실·서버실":"Server rooms","화장실·야간 취약 공간":"Restrooms and vulnerable spaces at night","옥외 배관·옥상 설비":"Outdoor piping and rooftop equipment","시설관리팀(기계·전기)":"Facility management team (mechanical and electrical)","약제부·감염관리실":"Pharmacy and infection control","행정실·안전관리 담당":"Administration and safety management","간호·돌봄 인력":"Nursing and care staff","병원":"Hospitals","음압·청정 구역 차압 관리":"Differential pressure control in negative-pressure and clean areas","음압격리실·수술실은 문 개폐와 공조 상태에 따라 차압이 흔들립니다. 간호 인력이 차압계를 수시로 확인해야 합니다.":"Differential pressure in negative-pressure isolation rooms and operating rooms fluctuates with door openings and HVAC conditions. Nursing staff must check pressure gauges frequently.","약제·검체 보관 이탈":"Pharmacy and specimen storage excursions","약제부·진단검사실 냉장고와 연구용 딥프리저가 많아 야간에 고장이 나면 대응이 늦어집니다.":"Pharmacies and clinical labs have many refrigerators and research deep freezers, so failures at night are responded to late.","음압격리실·수술실":"Negative-pressure isolation rooms and operating rooms","약제부·진단검사실":"Pharmacy and clinical laboratory","의료가스·발전기실":"Medical gas and generator room","초중고":"K-12 schools","급식실 냉장 보관 기록":"Cafeteria cold storage records","급식실 냉장·냉동고 온도를 매일 수기로 기록하고, 휴일에 생긴 고장은 다음 조리일에야 발견합니다.":"Cafeteria refrigerator and freezer temperatures are logged by hand every day, and failures on holidays are found only on the next cooking day.","급식실·식재료 창고":"Cafeteria and food storage","교실·특별실":"Classrooms and specialty rooms","보일러실·급수시설":"Boiler room and water supply","대학·연구실":"Universities and research labs","연구실 딥프리저 이탈":"Lab deep freezer excursions","연구실별로 딥프리저를 관리하지만 야간·방학 중 고장을 알릴 체계가 없어 시료 손실이 반복됩니다.":"Each lab manages its own deep freezers, but with no system to report failures at night or during breaks, sample losses keep recurring.","실험실 안전 환경 확인":"Checking lab safety conditions","흄후드 배기 상태, 가스검지기 경보, 누수를 연구실 안전 점검 때만 확인하는 경우가 많습니다.":"Fume hood exhaust, gas detector alarms and leaks are often checked only during lab safety inspections.","연구실·공용 장비실":"Labs and shared equipment rooms","흄후드·가스 사용 구역":"Fume hoods and gas use areas","기숙사·강의동 기계실":"Dormitory and lecture hall mechanical rooms","요양·복지시설":"Nursing homes and care facilities","야간 돌봄 공백":"Night-time care gaps","야간에는 소수 인원이 여러 생활실을 맡아 도움 요청과 출입문 개폐를 즉시 알기 어렵습니다.":"At night, a few staff cover many living quarters, making it hard to know immediately about calls for help or doors opening.","생활실·침실":"Living quarters and bedrooms","화장실·목욕실":"Restrooms and bathrooms","출입구·비상구":"Entrances and emergency exits","발전소·수처리장·변전소·플랜트는 넓은 부지에 펌프·팬·변압기·배관이 흩어져 있고, 무인 또는 소수 인원으로 운영되는 곳이 많습니다. SCADA가 핵심 계통을 보더라도 보조 설비와 외곽 구간은 순회점검에 의존하는 경우가 많습니다.":"Power plants, water treatment plants, substations and industrial plants have pumps, fans, transformers and piping spread across large sites, and many are unmanned or run by small crews. Even when SCADA covers core systems, auxiliary equipment and outlying areas often still depend on manual rounds.","보조 회전설비 돌발 고장":"Unexpected failures of auxiliary rotating equipment","급수·냉각수·약품 펌프, 송풍기, 냉각팬 같은 보조 설비는 SCADA 감시 범위 밖인 경우가 많아 진동 증가를 순회 중에야 발견합니다.":"Auxiliary equipment such as feedwater, cooling water and chemical pumps, blowers and cooling fans often falls outside SCADA coverage, so rising vibration is found only during rounds.","넓은 부지 순회점검 부담":"Burden of manual rounds across large sites","외곽 펌프장·밸브실·탱크를 사람이 돌며 확인하고 점검표를 작성합니다. 악천후나 야간에는 점검 간격이 벌어집니다.":"Staff walk to outlying pump stations, valve rooms and tanks to check them and fill out inspection sheets. In bad weather or at night, inspection intervals grow longer.","계측 추가 배선의 어려움":"Difficulty wiring additional instrumentation","옥외 장거리 구간과 위험 구역은 케이블 포설과 운전 중 작업 허가가 필요해, 필요한 계측점 추가를 뒤로 미루게 됩니다.":"Long outdoor runs and hazardous areas require cable laying and hot-work permits during operation, so needed measurement points get postponed.","가스·유해가스 노출 위험":"Gas and toxic gas exposure risk","가스 배관·밸브실, 하수·슬러지 처리 구간은 누설과 H2S 발생 위험이 있지만, 고정식 검지기 경보가 현장 수신반에만 표시되기도 합니다.":"Gas piping, valve rooms and sewage and sludge treatment areas carry leak and H2S risk, yet fixed gas detector alarms may show only on local annunciator panels.","연료·원수 공급 설비":"Fuel and raw water supply equipment","보일러·터빈 보조설비":"Boiler and turbine auxiliaries","냉각수·순환수 계통":"Cooling water and circulating water systems","변압기·전기실":"Transformers and electrical rooms","약품·가스 설비실":"Chemical and gas equipment rooms","배출·폐수 처리 설비":"Discharge and wastewater treatment equipment","외곽 설비·무인 시설":"Outlying equipment and unmanned facilities","운전·발전팀(교대 운전)":"Operations and generation team (shift operation)","기계·전기 정비팀":"Mechanical and electrical maintenance team","안전환경(HSE)팀":"Health, safety and environment (HSE) team","계측제어·디지털전환팀":"Instrumentation, control and digital transformation team","발전":"Power generation","보조설비 정지와 출력 제약":"Auxiliary equipment stoppages and output constraints","송풍기·급수펌프·냉각수 펌프·미분기 등 보조설비 이상이 주기기 운전 제약으로 번집니다. 예비기로 전환한 뒤에도 원인 설비 확인이 늦습니다.":"Faults in auxiliaries such as fans, feedwater pumps, cooling water pumps and pulverizers escalate into operating constraints on main equipment. Even after switching to standby units, identifying the faulty equipment is slow.","환경설비(탈황·집진)":"Environmental equipment (desulfurization, dust collection)","연료 취급 설비":"Fuel handling equipment","상하수도·수처리":"Water, wastewater and water treatment","원거리 펌프장·배수지 관리":"Managing remote pump stations and reservoirs","가압장·중계 펌프장·배수지가 흩어져 있어 펌프 이상과 수위 변화를 순회나 일부 원격 신호로만 확인합니다.":"Booster stations, relay pump stations and distribution reservoirs are scattered, so pump faults and level changes are checked only through rounds or a few remote signals.","취수·가압 펌프장":"Intake and booster pump stations","생물반응조·송풍기실":"Bioreactor tanks and blower room","유입·슬러지 처리동":"Influent and sludge treatment building","변전·배전·ESS":"Substations, distribution and ESS","무인 변전·ESS 설비 감시":"Monitoring unmanned substations and ESS","무인 변전소와 ESS 설비는 보호 계전 신호 외에 실온·배터리실 환경과 출입 이력을 상시로 보기 어려워 순회 때 확인합니다.":"At unmanned substations and ESS facilities, room temperature, battery room conditions and access history are hard to monitor continuously beyond protective relay signals, so they are checked during rounds.","변압기·수배전반":"Transformers and switchgear","ESS 배터리실":"ESS battery room","무인 변전소 외곽":"Unmanned substation perimeter","정유·가스·석유화학":"Refining, gas and petrochemicals","방폭 구역 설비 상태 확인":"Checking equipment condition in explosion-proof areas","방폭 구역의 펌프·팬·에어쿨러는 계측 추가 공사가 어려워 순회 점검과 휴대형 진동계 측정에 의존합니다.":"Pumps, fans and air coolers in explosion-proof areas are hard to instrument, so sites rely on manual rounds and handheld vibration meters.","넓은 부지의 누설 확인":"Checking for leaks across large sites","탱크팜·배관랙·출하 설비의 누설을 순회로 확인하고, 고정식 검지기 경보는 현장 수신반 중심으로 관리됩니다.":"Leaks at tank farms, pipe racks and loading facilities are checked during rounds, and fixed gas detector alarms are managed mainly from local annunciator panels.","공정 펌프·에어쿨러":"Process pumps and air coolers","탱크팜·배관랙":"Tank farms and pipe racks","출하·저장 설비":"Loading and storage facilities","태양광·풍력":"Solar and wind","원격지 설비 이상 인지 지연":"Delayed awareness of faults at remote sites","인버터·접속반·수배전반 이상이나 인버터실 냉방 정지를 현장에 가서야 확인하는 경우가 많아, 발전 손실 시간이 길어집니다.":"Faults in inverters, combiner boxes and switchgear, or cooling failures in inverter rooms, are often confirmed only by going to the site, prolonging generation losses.","인버터실·전기실":"Inverter room and electrical room","접속반·어레이 구역":"Combiner boxes and array areas","풍력 타워 하부":"Wind turbine tower base","식품·농수산 현장은 원료 입고부터 가공·보관·조리, 사육·재배까지 온도와 전원이 곧 품질이자 생물의 생존 조건입니다. 사람이 없는 야간의 냉장 이탈이나 정전은 폐기와 폐사로 바로 이어지므로 상시 기록과 즉시 알림이 필요합니다.":"In food, agriculture and fisheries, temperature and power define quality and even the survival of livestock and crops, from receiving raw materials through processing, storage and cooking to raising and growing. Refrigeration excursions or power outages at night when no one is around lead directly to spoilage and die-offs, so continuous records and instant alerts are essential.","냉장·냉동 설비 야간 이탈":"Refrigeration and freezer excursions at night","원료·완제품 냉장고와 냉동고는 야간·휴일에 고장 나도 온도가 서서히 올라, 다음 작업 시작 때 발견되는 경우가 많습니다.":"When raw material or finished goods refrigerators and freezers fail at night or on holidays, the temperature rises gradually and the problem is often found only when work starts again.","CCP 온도 기록 수기 부담":"Burden of manual CCP temperature logs","가열·냉각·보관 CCP 온도를 작업자가 정해진 시간마다 적는 방식은 바쁜 시간에 누락되고, 심사 전 기록 정리가 몰립니다.":"Having workers write down heating, cooling and storage CCP temperatures at set times leads to missed entries during busy periods and a rush to organize records before audits.","정전·설비 정지로 인한 폐사":"Die-offs from power outages and equipment stoppages","양식장 순환펌프·블로어나 축사 환기팬이 정전으로 멈추면 생물 피해가 빠르게 생기는데, 농장에는 사람이 없는 시간이 많습니다.":"When fish farm circulation pumps and blowers or barn ventilation fans stop during an outage, livestock and fish suffer quickly, yet farms are often unattended.","여러 매장·농장 분산 관리":"Managing multiple dispersed stores and farms","프랜차이즈 매장, 여러 동의 축사·온실처럼 관리 대상이 흩어져 있어 한 사람이 모든 곳을 수시로 확인하기 어렵습니다.":"With franchise stores or multiple barns and greenhouses spread out, one person cannot check every location frequently.","원료 입고·검수":"Raw material receiving and inspection","원료·완제품 냉장·냉동창고":"Raw material and finished goods cold and frozen storage","전처리·가공실":"Pre-processing and processing rooms","가열·살균·냉각 공정":"Heating, sterilization and cooling processes","유틸리티(보일러·냉동기)":"Utilities (boilers, refrigeration)","폐수처리·집수조":"Wastewater treatment and collection tanks","출하 대기·상차":"Shipping staging and loading","생산·품질(HACCP팀)":"Production and quality (HACCP team)","공무·설비팀":"Engineering and maintenance team","가맹 운영(슈퍼바이저)":"Franchise operations (supervisors)","농장·양식장 운영자":"Farm and fish farm operators","식품 제조":"Food manufacturing","냉각 공정 온도 관리":"Cooling process temperature control","가열 후 냉각 공정은 정해진 시간 안에 온도를 낮춰야 하는데, 냉각기 성능 저하를 수기 기록만으로 알아차리기 어렵습니다.":"After heating, products must be cooled within a set time, but manual logs alone make it hard to notice declining chiller performance.","냉각실·급속냉동기":"Cooling room and blast freezer","상온 제품 창고":"Ambient product warehouse","공기압축기·보일러실":"Air compressor and boiler room","외식·프랜차이즈":"Restaurants and franchises","폐점 후 매장 냉장고 고장":"Store refrigerator failures after closing","폐점 후나 휴무일에 냉장·냉동고가 멈추면 다음 영업 준비 때 발견되어 식재료를 폐기하고 일부 메뉴를 팔지 못합니다.":"When refrigerators and freezers stop after closing or on closed days, the problem is found while preparing for the next service, forcing ingredients to be discarded and some menu items to go unsold.","주방 배기·가스 설비 관리":"Kitchen exhaust and gas equipment management","주방 후드 배기팬 이상과 가스 연소기구 주변 CO 상승은 바쁜 조리 중에는 체감하기 어렵습니다.":"Kitchen hood exhaust fan faults and rising CO around gas appliances are hard to notice during busy cooking.","주방 냉장·냉동고":"Kitchen refrigerators and freezers","조리 구역·후드":"Cooking area and hoods","매장 분전반":"Store distribution panel","양식":"Aquaculture","야간 정전·펌프 정지":"Night-time power outages and pump stoppages","순환펌프·블로어가 정전이나 차단기 트립으로 멈추면 수조 환경이 빠르게 나빠지는데, 야간에는 이를 바로 알아차리기 어렵습니다.":"When circulation pumps and blowers stop due to an outage or breaker trip, tank conditions deteriorate quickly, but this is hard to notice right away at night.","계절별 수온 급변":"Seasonal water temperature swings","고수온기와 저수온기에는 취수 수온과 수조 수온이 짧은 시간에 변해 사육 관리 판단이 늦어지기 쉽습니다.":"During high- and low-temperature seasons, intake and tank water temperatures change within a short time, which can delay husbandry decisions.","사육 수조":"Rearing tanks","펌프·블로어실":"Pump and blower room","취수·배수 설비":"Water intake and discharge equipment","축산":"Livestock","환기 정지와 고온 스트레스":"Ventilation stoppages and heat stress","여름철 환기팬이 정전이나 모터 고장으로 멈추면 축사 내부 온도가 빠르게 오르는데, 동이 많아 바로 확인하기 어렵습니다.":"When ventilation fans stop in summer due to an outage or motor failure, barn temperatures rise quickly, but with many barns it is hard to check right away.","밀폐형 축사 내부":"Inside enclosed barns","환기팬·쿨링패드":"Ventilation fans and cooling pads","분뇨 저장조·처리시설":"Manure storage and treatment facilities","시설원예·스마트팜":"Greenhouses and smart farms","겨울철 야간 난방기 정지":"Heater shutdowns on winter nights","야간에 난방기가 연료 부족이나 고장으로 멈추면 온실 온도가 떨어지는데, 새벽 순찰 때에야 발견하는 경우가 많습니다.":"When heaters stop at night due to fuel shortage or failure, greenhouse temperatures drop, and this is often found only during early-morning patrols.","재배 베드·작물 구역":"Growing beds and crop areas","난방기·보일러실":"Heaters and boiler room","양액기·관수 설비":"Nutrient dosing and irrigation equipment","종교시설·소규모 매장·창고는 전담 시설 인력이 없거나 적고, 사람이 없는 시간이 깁니다. 누수·동파·정전·냉장고 고장 같은 작은 이상이 큰 손실로 번지기 전에 알림을 받는 것이 핵심입니다.":"Religious facilities, small stores and warehouses have few or no dedicated facility staff and long unattended hours. The key is getting alerts before small problems like leaks, pipe freezing, power outages and refrigerator failures turn into major losses.","무인 시간대 이상 발견 지연":"Delayed detection of problems during unmanned hours","영업 종료 후나 평일 비어 있는 시설에서 생긴 누수·정전을 다음 출근이나 방문 때에야 확인합니다.":"Leaks and power outages in facilities that are closed or empty on weekdays are found only at the next shift or visit.","겨울철 동파":"Winter pipe freezing","난방을 끈 공간이나 외기에 노출된 배관이 한파에 얼어 터지고, 날이 풀린 뒤에야 누수로 드러납니다.":"Pipes in unheated spaces or exposed to outdoor air freeze and burst in cold snaps, showing up as leaks only after the weather warms.","냉장·냉동 설비 고장":"Refrigeration and freezer equipment failures","매장 쇼케이스·냉동고 고장이나 차단기 트립은 밤사이 조용히 진행되어 아침에 재고 폐기로 이어집니다.":"Store display case or freezer failures and breaker trips progress quietly overnight and lead to discarded inventory in the morning.","노후 전기설비·에너지 낭비":"Aging electrical equipment and wasted energy","오래된 분전반에 냉난방기·전열기를 추가하며 과부하가 생기고, 사람이 없는데도 설비가 켜져 있는 경우가 많습니다.":"Adding heating, cooling and electric heaters to old distribution panels causes overloads, and equipment is often left running when no one is there.","출입구·매장 공간":"Entrance and store area","냉장·냉동 설비":"Refrigeration and freezer equipment","분전반·전기실":"Distribution panel and electrical room","화장실·주방 배관":"Restroom and kitchen piping","보일러실·기계실":"Boiler room and mechanical room","창고·지하 공간":"Storage and basement spaces","시설·건물 관리 담당":"Facility and building management","매장 점주·운영 담당":"Store owner and operations","창고·보관 관리 담당":"Warehouse and storage management","종교시설":"Religious facilities","평일 빈 건물 관리":"Managing buildings left empty on weekdays","평일 난방을 끈 본당·교육관에서 동파나 누수가 생겨도 주말 행사 때에야 발견됩니다.":"Pipe freezing or leaks in main halls and education buildings with heating turned off on weekdays are found only at weekend services or events.","본당·예배 공간":"Main hall and worship space","보일러실·주방":"Boiler room and kitchen","방송·음향실":"Broadcast and sound room","소상공인 매장·사무실":"Small business stores and offices","영업 종료 후 냉장고 고장":"Refrigerator failures after closing","쇼케이스·냉동고 고장이나 차단기 트립이 밤사이 생기면 다음 날 개점 때 재고를 폐기합니다.":"When display cases or freezers fail or a breaker trips overnight, inventory is discarded at the next day's opening.","쇼케이스·냉장고":"Display cases and refrigerators","분전반·전열기":"Distribution panels and electric heaters","창고·보관 시설":"Warehouses and storage facilities","보관 환경 습기·결로":"Moisture and condensation in storage","환기가 부족한 창고는 계절에 따라 결로가 생겨 포장재·보관품이 상하지만, 주기적으로 확인하기 어렵습니다.":"Poorly ventilated warehouses develop seasonal condensation that damages packaging and stored goods, yet regular checks are hard to maintain.","무인 창고 출입·침수":"Access and flooding at unmanned warehouses","야간 셔터 개폐와 호우 때 바닥 물 고임을 사람이 없을 때 알 방법이 부족합니다.":"There are few ways to know about shutters opening at night or water pooling on the floor during heavy rain when no one is there.","보관 구역·랙":"Storage areas and racks","출입구·셔터":"Entrances and shutters","바닥·배수구":"Floors and drains","제조 현장은 설비 한 대의 정지가 라인 전체의 생산 차질로 이어집니다. 회전설비·유틸리티·전력 설비 상태를 사람이 순회하며 확인하는 방식은 야간·주말에 공백이 생기고, 이상 징후를 고장 직전까지 놓치기 쉽습니다.":"On the factory floor, a single machine stopping can disrupt the entire line. Checking rotating equipment, utilities and power equipment through manual rounds leaves gaps at night and on weekends, and warning signs are easily missed until just before failure.","회전설비 돌발 정지":"Unexpected stoppages of rotating equipment","모터·펌프·컴프레서·배기팬은 베어링 마모와 정렬 불량이 서서히 진행되다 한 번에 멈춥니다. 예방정비 주기가 실제 상태와 맞지 않아 정지 후에야 원인을 찾습니다.":"Bearing wear and misalignment in motors, pumps, compressors and exhaust fans progress gradually until the equipment stops all at once. Preventive maintenance intervals don't match actual condition, so causes are investigated only after a stoppage.","순회점검 기록의 공백":"Gaps in manual round records","설비·유틸리티 점검을 교대조가 점검표에 적어 관리합니다. 야간·휴일에는 점검 간격이 벌어지고, 수기 기록은 추이 분석에 활용하기 어렵습니다.":"Shift crews manage equipment and utility inspections on paper checklists. At night and on holidays, inspection intervals widen, and manual records are hard to use for trend analysis.","분전반·배전반 과열":"Distribution panel and switchboard overheating","설비 증설로 부하가 늘어도 분전반 상태는 정기 점검 때만 확인합니다. 상 불평형과 접속부 과열이 누적되어도 현장에서 알아채기 어렵습니다.":"Even as loads grow with added equipment, panel condition is checked only during scheduled inspections. Phase imbalance and connection overheating build up without being noticed on site.","경보가 제어반에서만 울림":"Alarms sound only at control panels","공조기·컴프레서·집진기 경보가 현장 제어반에서만 울려 담당자가 자리를 비우면 늦게 압니다. 중앙 시스템에 연결하려면 배선 공사가 필요합니다.":"Alarms from air handlers, compressors and dust collectors sound only at local control panels, so they are noticed late when staff are away. Connecting them to a central system requires wiring work.","원자재 입고·보관":"Raw material receiving and storage","가공·조립 라인":"Machining and assembly lines","열처리·도장·건조":"Heat treatment, painting and drying","유틸리티동":"Utility building","수배전반·분전반":"Switchgear and distribution panels","배관·폐수·약품 저장":"Piping, wastewater and chemical storage","설비보전팀(생산기술)":"Equipment maintenance team (production engineering)","유틸리티·공무팀":"Utilities and engineering team","안전환경(EHS)팀":"Environment, health and safety (EHS) team","생산관리·스마트팩토리(IT)팀":"Production management and smart factory (IT) team","반도체·디스플레이":"Semiconductors and displays","서브팹 유틸리티 정지":"Sub-fab utility stoppages","진공펌프·스크러버·칠러·배기팬이 서브팹에 흩어져 있어 순회로 상태를 봅니다. 한 대의 정지가 상부 공정 장비의 인터록으로 이어집니다.":"Vacuum pumps, scrubbers, chillers and exhaust fans are scattered across the sub-fab and checked on rounds. A single stoppage can trigger interlocks on process tools above.","클린룸(FAB)":"Cleanroom (fab)","서브팹(진공·스크러버)":"Sub-fab (vacuum pumps, scrubbers)","가스·케미컬 공급실":"Gas and chemical supply room","이차전지":"Rechargeable batteries","드라이룸 습도 이탈":"Dry room humidity excursions","드라이룸은 극저습을 유지해야 하지만 출입이나 제습기 이상으로 습도가 오르는 구간이 생깁니다. 이탈 시각과 지속시간을 정확히 남기기 어렵습니다.":"Dry rooms must maintain extremely low humidity, but personnel entry or dehumidifier faults cause periods of rising humidity. Accurately recording when excursions start and how long they last is difficult.","화성·에이징 구간 열 관리":"Heat management in formation and aging areas","충방전 장비가 밀집한 화성·에이징 구역은 발열이 크고, 랙별 온도 편차와 전원 이상을 사람이 계속 지켜볼 수 없습니다.":"Formation and aging areas packed with charge/discharge equipment generate a lot of heat, and staff cannot continuously watch rack-to-rack temperature differences and power faults.","전극 공정·드라이룸":"Electrode process and dry room","코팅·건조로":"Coating and drying ovens","화성·에이징실":"Formation and aging room","자동차·부품":"Automotive and parts","프레스·컨베이어 정지":"Press and conveyor stoppages","프레스 메인 모터·플라이휠과 차체·조립 컨베이어 구동부는 부하가 커 마모가 빠릅니다. 정지하면 후공정과 납품 일정이 함께 밀립니다.":"Press main motors and flywheels, and drive units on body and assembly conveyors, carry heavy loads and wear quickly. A stoppage delays downstream processes and delivery schedules alike.","프레스 공정":"Press shop","도장 공장":"Paint shop","조립 라인·컨베이어":"Assembly lines and conveyors","화학·소재":"Chemicals and materials","방폭 구역 계측 추가 부담":"Burden of adding instrumentation in explosion-proof areas","펌프·교반기 상태를 더 보고 싶어도 방폭 구역은 전선관 공사와 작업 허가가 필요해 계측 확대가 늦어집니다.":"Even when you want more visibility into pumps and agitators, explosion-proof areas require conduit work and work permits, which slows the expansion of monitoring.","유해가스·약품 누설 확인":"Checking for toxic gas and chemical leaks","저장 탱크·이송 배관 주변 누설을 순회와 고정식 검지기로 확인하지만, 검지기 경보가 현장 수신반에만 표시되는 경우가 많습니다.":"Leaks around storage tanks and transfer piping are checked through rounds and fixed gas detectors, but detector alarms often show only on local annunciator panels.","반응·교반 공정":"Reaction and mixing processes","탱크팜·이송 배관":"Tank farms and transfer piping","폐수·스크러버 설비":"Wastewater and scrubber equipment","일반 제조·기계":"General manufacturing and machinery","소수 인력의 설비 관리":"Equipment management with a small team","보전 담당자 한두 명이 공장 전체 설비를 맡아 이상 징후를 순회 중 우연히 발견하곤 합니다. 야간 무인 운전 시간에는 공백이 더 커집니다.":"With one or two maintenance staff covering all plant equipment, warning signs are often found by chance during rounds. The gap widens during unmanned night-time operation.","공작기계·가공 설비":"Machine tools and processing equipment","공기압축기실":"Air compressor room","수전·분전반":"Power intake and distribution panels","공공청사·국방·문화시설·지하 인프라는 넓은 부지와 여러 건물을 적은 인원이 관리하고, 야간·휴일 무인 시간이 깁니다. 정전·침수·누수 같은 설비 이상이 곧 대민 서비스 중단과 공공 자산 손상으로 이어지므로 상시 감시 체계가 필요합니다.":"Government buildings, defense and cultural facilities, and underground infrastructure involve large sites and many buildings managed by small teams, with long unmanned hours at night and on holidays. Equipment problems such as power outages, flooding and leaks quickly lead to public service disruptions and damage to public assets, so continuous monitoring is essential.","야간·휴일 무인 감시 공백":"Unmanned monitoring gaps at night and on holidays","당직 인원이 본관과 흩어진 부속 시설을 모두 돌기 어렵습니다. 기계실·전기실 이상이 다음 날 출근 후에야 확인되는 일이 반복됩니다.":"Duty staff can hardly cover both the main building and scattered annex facilities. Mechanical and electrical room problems are repeatedly found only after staff arrive the next day.","지하 공간 침수·누수":"Flooding and leaks in underground spaces","지하 기계실·전기실·주차장은 집중호우 때 배수펌프 고장이나 역류로 물이 차기 쉽습니다. 집수정 수위를 사람이 직접 봐야 해 대응이 늦어집니다.":"Basement mechanical rooms, electrical rooms and parking garages easily flood during heavy rain due to drainage pump failures or backflow. Sump pit levels must be checked in person, which delays response.","노후 전기설비 과열":"Overheating of aging electrical equipment","준공이 오래된 시설은 분전반 증설이 반복되어 부하가 한쪽으로 몰립니다. 열화상 점검은 주기적이라 그 사이의 과부하 변화를 알기 어렵습니다.":"In older facilities, repeated panel expansions concentrate load on one side. Thermal imaging inspections are periodic, so overload changes in between go unnoticed.","순회점검 기록 부담":"Burden of manual round records","소수 인원이 여러 동의 설비를 돌며 점검표를 수기로 채웁니다. 기록이 흩어져 있어 감사·인수인계 때 이력을 찾는 데 시간이 듭니다.":"A small team walks through equipment in multiple buildings and fills out inspection sheets by hand. With records scattered, finding history for audits and handovers takes time.","전기실·수배전반":"Electrical room and switchgear","기계실(냉난방·펌프)":"Mechanical room (HVAC, pumps)","지하 주차장·집수정":"Underground parking and sump pits","전산실·통신실":"Server and telecom rooms","민원실·다중이용 공간":"Public service counters and high-occupancy spaces","문서고·자료 보관실":"Archives and records storage","옥외 배관·저수조":"Outdoor piping and water storage tanks","안전·재난관리 담당":"Safety and disaster management","청사 보안·운영 담당":"Building security and operations","전산·정보통신 담당":"IT and telecommunications","국방·군 시설":"Defense and military facilities","분산 시설 무인 감시":"Unmanned monitoring of dispersed facilities","창고·발전기실·급수시설이 넓게 흩어져 있어 순찰 사이의 이상을 알기 어렵습니다. 보안상 유선 공사와 외부망 연결에도 제약이 많습니다.":"Warehouses, generator rooms and water supply facilities are widely dispersed, making it hard to detect problems between patrols. Security requirements also restrict wiring work and external network connections.","물자·장비 창고":"Supply and equipment warehouses","비상발전기실":"Emergency generator room","급수·저수 시설":"Water supply and storage facilities","공공청사·지자체 시설":"Government buildings and municipal facilities","방문객 공간 환경 민원":"Visitor area comfort complaints","민원실·회의실은 시간대별 재실 인원 편차가 커서 온도·환기 민원이 반복됩니다. 설비 운전을 조정할 근거 데이터가 부족합니다.":"Occupancy in public service counters and meeting rooms varies widely by time of day, leading to repeated temperature and ventilation complaints. There is little data to justify adjusting equipment operation.","민원실·대회의실":"Public service counters and large conference rooms","공영주차장·지하층":"Public parking and basement levels","공공 체육시설 설비":"Public sports facility equipment","박물관·미술관·공연장":"Museums, galleries and performance venues","수장고 온습도 편차":"Temperature and humidity variation in collection storage","항온항습기 이상이나 잦은 문 개폐로 수장고 습도가 흔들립니다. 수기 기록으로는 짧은 시간의 편차를 놓치기 쉽습니다.":"CRAC faults or frequent door openings make humidity in collection storage fluctuate. Manual logs easily miss short-term variations.","휴관일 누수 발견 지연":"Delayed leak detection on closed days","휴관일·야간에 공조 배관이나 스프링클러 배관 누수가 생기면 전시실로 번진 뒤에야 발견됩니다.":"When HVAC or sprinkler piping leaks on closed days or at night, it is found only after spreading into the galleries.","수장고":"Collection storage","전시실":"Galleries","공연장 무대·기계실":"Stage and mechanical room of performance venues","지하철·터널·지하 공동구":"Subways, tunnels and underground utility tunnels","배수펌프장 이상 인지 지연":"Delayed awareness of drainage pump station faults","배수펌프장이 역사·구간마다 흩어져 있어 펌프 고장과 수위 상승을 현장에서만 확인하는 경우가 많습니다.":"Drainage pump stations are scattered across stations and sections, so pump failures and rising water levels are often confirmed only on site.","공동구 순회점검 부담":"Burden of patrolling utility tunnels","긴 공동구를 사람이 걸으며 누수·온도·출입 상태를 확인합니다. 밀폐 구간에서는 작업자 안전 확인도 함께 필요합니다.":"Staff walk long utility tunnels to check leaks, temperature and access. In enclosed sections, worker safety must also be confirmed.","배수펌프장·집수정":"Drainage pump stations and sump pits","공동구·케이블 구간":"Utility tunnels and cable sections","환기실·밀폐 구간":"Ventilation rooms and enclosed sections","주거·숙박 시설은 사람이 생활하고 머무는 공간이라 누수·동파·전기 이상이 곧 거주자 피해와 민원, 영업 손실로 이어집니다. 세대·객실 안은 수시로 들어갈 수 없어 공용부와 공실 중심의 상시 감시가 필요합니다.":"Residential and lodging facilities are where people live and stay, so leaks, pipe freezing and electrical faults quickly become resident damage, complaints and lost business. Since units and guest rooms cannot be entered at will, continuous monitoring focused on common areas and vacant units is needed.","세대 간 누수 분쟁":"Leak disputes between units","상층 세대 배관이나 욕실 방수 문제로 생긴 누수는 아래층 천장에서 처음 드러나고, 발원지 확인과 책임 공방에 시간이 걸립니다.":"Leaks from upstairs unit piping or bathroom waterproofing failures first appear on the ceiling below, and tracing the source and settling responsibility takes time.","복도식 세대 계량기함, 옥상 물탱크 배관, 비어 있는 세대·객실의 배관은 한파 때 얼어 터진 뒤에야 발견됩니다.":"Piping in corridor-side unit meter boxes, rooftop water tanks, and vacant units and guest rooms is found only after it freezes and bursts in a cold snap.","지하 주차장·기계실 침수":"Flooding of underground parking and mechanical rooms","집중호우 때 지하주차장과 기계실·전기실로 물이 들어와도 배수펌프 상태는 사람이 내려가서 확인해야 합니다.":"Even when water flows into underground parking, mechanical rooms and electrical rooms during heavy rain, someone has to go down and check drainage pump status.","인력 대비 넓은 관리 범위":"Large area to cover with limited staff","관리사무소·시설팀 인원은 한정되어 있는데 동·층·객실이 많아, 순찰과 점검 기록이 형식적으로 흐르기 쉽습니다.":"Management office and facilities staff are limited while buildings, floors and rooms are many, so patrols and inspection records easily become a formality.","수변전실·분전반":"Substation and distribution panels","물탱크실·옥상 배관":"Water tank room and rooftop piping","세대 계량기함·PD":"Unit meter boxes and pipe ducts","커뮤니티·공용시설":"Community and shared facilities","공실·장기 비움 공간":"Vacant and long-term empty spaces","관리사무소·시설과장":"Management office and facilities manager","호텔 시설·엔지니어링팀":"Hotel facilities and engineering team","임대·공실 관리 담당":"Leasing and vacancy management","안전관리자":"Safety manager","아파트·공동주택":"Apartments and multi-family housing","복도식 계량기함 동파":"Pipe freezing in corridor-side meter boxes","복도식·노후 단지는 세대 계량기함이 외기에 노출되어 한파 때마다 동파가 반복되고, 관리사무소는 안내 방송과 순찰에 의존합니다.":"In corridor-type and older complexes, unit meter boxes are exposed to outdoor air, so pipe freezing recurs in every cold snap, and management offices rely on announcements and patrols.","동별 계량기함":"Meter boxes in each building","지하 기계실·전기실":"Basement mechanical and electrical rooms","호텔·리조트":"Hotels and resorts","객실 누수와 판매 중단":"Guest room leaks and rooms taken out of service","객실 욕실·FCU 드레인 누수는 투숙객 신고로 처음 아는 경우가 많고, 아래층 객실까지 번지면 여러 객실을 판매하지 못합니다.":"Leaks from guest bathrooms and FCU drains are often first learned about from guest reports, and if they spread to rooms below, several rooms cannot be sold.","주방·세탁실 설비 정지":"Kitchen and laundry equipment stoppages","연회 주방 냉장고, 세탁실 대형 세탁·건조기, 온수 보일러가 멈추면 운영 전반에 연쇄 영향이 생깁니다.":"When banquet kitchen refrigerators, large laundry washers and dryers, or hot water boilers stop, the effects ripple across operations.","객실층 PD·FCU":"Guest floor pipe ducts and FCUs","연회·조리 주방":"Banquet and cooking kitchens","수영장·사우나 설비":"Pool and sauna equipment","임대주택·기숙사·공실 관리":"Rental housing, dormitories and vacancy management","공실 기간 사고 늦은 발견":"Late detection of incidents during vacancies","퇴거 후 다음 입주까지 비어 있는 세대에서 보일러 정지, 동파, 누수가 생기면 입주 청소나 사전 점검 때에야 발견됩니다.":"When boiler shutdowns, pipe freezing or leaks occur in units left empty between tenants, they are found only during move-in cleaning or pre-move-in inspections.","공실 세대·호실":"Vacant units and rooms","기숙사 공용 공간":"Dormitory common areas","세대 보일러·분전반":"Unit boilers and distribution panels"},"cases":{"samsung-biologics":{"name":"Biopharmaceutical manufacturing plant","industryText":"Healthcare · Biotech","tagline":"Unified visibility of the mechanical rooms, air handling rooms and labs along the Songdo campus bioreactor lines on a single wireless platform","challenges":["Difficulty securing the vibration data needed to apply AI predictive maintenance models to rotating equipment (HVAC, motors)","Wired sensor deployment would sharply increase installation costs in piping and explosion-proof areas","No unified visibility, with monitoring systems fragmented by equipment and vendor"],"results":["Manual inspection and logging time","Equipment fault response time","Environmental data traceability","Rotating equipment vibration dataset secured"]},"veolia":{"name":"Energy and water treatment operations","industryText":"Energy","tagline":"Industrial IoT infrastructure for remote monitoring of numerous motors, chillers, boilers and air handlers, as well as leachate and toxic gas (energy use and equipment safety)","challenges":["Heat meters, flow meters and equipment power use were measured manually on site, making continuous energy data collection difficult","Ongoing accident risk from leachate management and toxic gas at the eco-cycle site","No system to monitor dispersed motors, chillers, boilers and air handlers in one place"],"results":["Energy use reduction","Leachate and gas leak detection","Unplanned pump downtime","Asset operations ROI"]},"samsung":{"name":"Semiconductor and electronics manufacturing facility","industryText":"Semiconductor R&D","tagline":"Equipment alarms, 4-20mA instrument data transmission, piping and chemical leak monitoring, and SCADA-integrated monitoring","challenges":["Lab piping and equipment leaks could not be addressed in real time and were noticed only after secondary damage occurred","Deploying many wired sensor products meant high costs and difficult unified monitoring","Wired sensors cannot be installed inside explosion-proof facilities"],"results":["Chemical leak detection and response time","Real-time collection rate of instrument data","Wireless environmental monitoring deployed","Unified response time for environmental anomalies"]},"microsoft":{"name":"Hyperscale data center","industryText":"IT · Data center","tagline":"A single visibility platform for racks, HVAC, leaks and power across global Azure data centers","challenges":["Slight temperature and humidity variations across thousands of server racks affect hardware life over the long term","A leak or fire in the data center translates directly into equipment losses in the hundreds of millions of won","Inefficient cooling and power operation worsens PUE and drives up operating costs"],"results":["Environment-related downtime","Cooling efficiency","Incident response time","Equipment loss prevented per leak or incident"]},"hyundai-motors":{"name":"Automotive manufacturing","industryText":"Automotive · Transportation","tagline":"Unified monitoring of paint, welding and assembly lines at global plants in Ulsan, Alabama and the Czech Republic","challenges":["Unplanned paint booth stoppages affected the entire line minute by minute, increasing equipment downtime","Paint quality defects caused by temperature and humidity variation in paint booths","No way to manage air quality data across the paint shop in one place"],"results":["Unplanned paint booth downtime","Paint defect rate","Predicting equipment failures in advance","Line equipment uptime"]},"hdc-labs":{"name":"Large mixed-use building FM operations","industryText":"Construction · Real estate","tagline":"A smart IoT space platform across all building, residential and real estate operations","challenges":["HVAC, lighting and power operations across many buildings were managed building by building, preventing unified analysis","Space occupancy was not visible, so opportunities to optimize leased space and save energy were lost","Serious incidents (power outages, fires, flooding, gas) could only be handled after the fact, increasing tenant claims and repair costs"],"results":["Installation investment vs. wired","Facility operating costs","HVAC efficiency","Tenant satisfaction"]},"us-army":{"name":"Military and public infrastructure facility","industryText":"Defense","tagline":"Remote monitoring of strategic assets, ammunition depots, power equipment and fuel storage across the base on a single secure platform","challenges":["Temperature, humidity, fire, leaks, power loss and intrusion at ammunition depots, supply warehouses and telecom rooms were checked only by foot patrols, leaving blind spots at night and in bad weather","Unplanned stoppages of emergency generators and power equipment directly threaten operational continuity","Difficult to track leaks and levels of fuel storage tanks across a vast base in real time"],"results":["Unmanned remote monitoring","Patrol staffing burden","Asset anomaly response time","Strategic asset availability"]},"gs-eps":{"name":"Power generation and energy facility","industryText":"Power generation · Utilities","tagline":"Predictive maintenance on a single platform for gas and steam turbines, boilers, transformers and fuel equipment at a combined-cycle power plant","challenges":["Unplanned stoppages of rotating equipment such as gas and steam turbines and generators lead directly to generation losses and grid impact","Temperature and vibration anomalies in boilers, heat exchangers and transformers are hard to catch early with periodic inspections alone","Fuel and lube oil leaks and piping problems were detected by manual rounds, leaving ongoing safety and environmental risk"],"results":["Unplanned downtime","Equipment uptime","Leak detection time","Generation efficiency"]},"walmart":{"name":"Retail cold chain","industryText":"Distribution · Retail","tagline":"Wireless, unified monitoring of temperature integrity across the entire cold chain, from stores to distribution centers","challenges":["Dozens of refrigeration and freezer units per store were checked by hand, delaying awareness of incidents at night and on weekends","No unified visibility, with temperature data scattered by equipment","Inconsistent response across stores in multi-store operations"],"results":["Food spoilage losses","Incident detection time","Temperature data traceability","Equipment uptime"]},"sk-ecoplant":{"name":"SK ecoplant","industryText":"Construction · Real estate","tagline":"Wireless IoT monitoring solution deployed at SK ecoplant sites.","challenges":[],"results":[]},"hyundai-enc":{"name":"Hyundai E&C","industryText":"Construction · Real estate","tagline":"Wireless IoT monitoring solution deployed at Hyundai E&C sites.","challenges":[],"results":[]},"hyundai-engineering":{"name":"Hyundai Engineering","industryText":"Construction · Real estate","tagline":"Wireless IoT monitoring solution deployed at Hyundai Engineering sites.","challenges":[],"results":[]},"hoban":{"name":"Hoban Construction","industryText":"Construction · Real estate","tagline":"Wireless IoT monitoring solution deployed at Hoban Construction sites.","challenges":[],"results":[]},"seantex":{"name":"Seantex","industryText":"Construction · Real estate","tagline":"Wireless IoT monitoring solution deployed at Seantex sites.","challenges":[],"results":[]},"emart":{"name":"E-mart","industryText":"Retail · Consumer goods","tagline":"Wireless IoT monitoring solution deployed at E-mart sites.","challenges":[],"results":[]},"hanwha-snc":{"name":"Hanwha S&C Solutions","industryText":"IT · Data center","tagline":"Wireless IoT monitoring solution deployed at Hanwha S&C Solutions sites.","challenges":[],"results":[]},"samchully":{"name":"Samchully","industryText":"Energy","tagline":"Wireless IoT monitoring solution deployed at Samchully sites.","challenges":[],"results":[]},"lx":{"name":"LX","industryText":"Energy","tagline":"Wireless IoT monitoring solution deployed at LX sites.","challenges":[],"results":[]},"hyu-guri-hospital":{"name":"Hanyang University Guri Hospital","industryText":"Healthcare · Biotech","tagline":"Wireless IoT monitoring solution deployed at Hanyang University Guri Hospital.","challenges":[],"results":[]},"cj-feedncare":{"name":"CJ Feed&Care","industryText":"Food service","tagline":"Wireless IoT monitoring solution deployed at CJ Feed&Care sites.","challenges":[],"results":[]},"aquafarm":{"name":"Fish farm","industryText":"Food service","tagline":"Wireless IoT monitoring solution deployed at a fish farm.","challenges":[],"results":[]},"gangnam":{"name":"Gangnam-gu","industryText":"Public sector · Nonprofit","tagline":"Wireless IoT monitoring solution deployed at Gangnam-gu facilities.","challenges":[],"results":[]},"keco":{"name":"Korea Environment Corporation","industryText":"Defense","tagline":"Wireless IoT monitoring solution deployed at Korea Environment Corporation sites.","challenges":[],"results":[]},"shinhan-univ":{"name":"Shinhan University","industryText":"Education","tagline":"Wireless IoT monitoring solution deployed at Shinhan University.","challenges":[],"results":[]},"songhyun-elem":{"name":"Songhyun Elementary School","industryText":"Education","tagline":"Wireless IoT monitoring solution deployed at Songhyun Elementary School.","challenges":[],"results":[]},"cbre":{"name":"CBRE","industryText":"Construction · Real estate","tagline":"Occupancy, energy, HVAC and facilities for 100,000+ commercial buildings worldwide on a single operations platform","challenges":["HVAC, lighting and power operations across many buildings were managed building by building, preventing unified analysis","Space occupancy was not visible, so opportunities to optimize leased space and save energy were lost","Facility leaks and incidents could only be handled after the fact, increasing tenant claims and repair costs"],"results":["Operating costs","HVAC efficiency","Occupancy visibility","Tenant satisfaction"]},"exxonmobil":{"name":"ExxonMobil","industryText":"Energy","tagline":"Industrial IoT infrastructure for remote, unified monitoring of pumps, compressors, tanks and piping across multiple refineries","challenges":["Unplanned stoppages of aging pumps and compressors lead directly to production losses across the line, and vibration and temperature data were hard to collect continuously","Gas and fluid leaks across vast plant sites were detected only by worker rounds, leaving constant accident risk","Manual checks of tank levels and pipe pressure limited operating efficiency and made asset ROI analysis impossible"],"results":["Unplanned downtime","Average equipment MTBF","Leak detection time","Asset ROI"]}}};
